<template>
  <el-dialog title="订单问题与处理记录" :visible.sync="visible" width="min(1000px, 96vw)" append-to-body :close-on-click-modal="false" class="order-issues-dialog">
    <div v-loading="loading" class="issue-dialog-body"><p class="issue-order-number">{{ report.order_sn || orderSn }}</p><el-alert v-if="error || report.issue_sync_error" :title="error || report.issue_sync_error" type="warning" :closable="false" show-icon /><p class="issue-caption">最近核对：{{ report.issue_synced_at || '尚未完成' }}。提醒与预占结果分别展示；确认知悉不会解除相关阻断。</p>
      <el-tabs v-model="tab"><el-tab-pane :label="'当前问题（' + active.length + '）'" name="active"><el-empty v-if="!loading && !error && !active.length" :description="report.issue_synced_at ? '暂无当前问题，可查看历史处理记录' : '问题尚未核对，请刷新核对'" :image-size="60" /><article v-for="issue in active" :key="issue.id" class="issue-card"><div class="issue-card-heading"><el-tag :type="tone(issue)" size="small">{{ category(issue) }}</el-tag><span>{{ scope(issue) }} · {{ stage(issue) }}</span><strong>{{ issue.sku_sn || '订单整体' }}</strong><el-tag size="mini" type="info" effect="plain">{{ states[issue.state] || issue.state }}</el-tag><span :class="Number(issue.blocking) ? 'blocking' : 'issue-caption'">{{ Number(issue.blocking) ? '阻断相关处理' : '提醒，不改变已确认的履约结果' }}</span></div><p class="issue-message">{{ issue.message }}</p><div class="issue-evidence"><span v-for="fact in facts(issue.evidence)" :key="fact">{{ fact }}</span></div><el-collapse><el-collapse-item :title="issue.domain === 'PLATFORM_SHIPPING' ? '查看异常包裹与回传任务' : '查看核对依据与预占时快照'" :name="String(issue.id)"><p class="issue-caption">依据：{{ basis(issue.evidence) }} · 首次发现 {{ issue.first_seen }} · 最近核对 {{ issue.last_seen }}</p><div v-if="issue.domain === 'PLATFORM_SHIPPING' && issue.evidence"><div v-for="task in issue.evidence.tasks || []" :key="task.id" class="issue-caption">回传任务 {{ task.id }} · 包裹 {{ task.package_id }} · {{ task.quantity }} 件 · {{ task.state }} · {{ task.last_error }}</div><p class="issue-caption">请到发货单的“平台发货回传”查看原快照、重试或核对回执。</p></div><div v-else-if="issue.evidence && issue.evidence.last_decision && issue.evidence.last_decision.observed_at" class="decision-snapshot"><p>最近预占尝试快照：{{ issue.evidence.last_decision.observed_at }}</p><span>公司可用 {{ issue.evidence.last_decision.company_available }} 件</span><span>渠道额度 {{ issue.evidence.last_decision.channel_quota }} 件</span><span>公共补占需求 {{ issue.evidence.last_decision.public_needed }} 件</span></div><p v-else class="issue-caption">此记录未保存预占时快照，以上为当前余额核对，不倒推历史库存。</p><p v-if="issue.acknowledged_at" class="issue-caption">确认人：{{ issue.acknowledged_by }} · {{ issue.acknowledged_at }} · {{ issue.acknowledgement }}</p></el-collapse-item></el-collapse><el-button v-if="issue.state === 'OPEN'" v-hasPermi="['order:order:review']" type="text" :disabled="!!busy" @click="acknowledge(issue)">确认已知悉</el-button></article></el-tab-pane>
        <el-tab-pane label="历史与处理记录" name="history"><el-table :data="report.events || []" size="small" empty-text="尚无问题处理记录"><el-table-column label="时间 / 处理人" min-width="190"><template slot-scope="s">{{ s.row.create_time }}<div class="issue-caption">{{ s.row.actor }}</div></template></el-table-column><el-table-column label="动作" width="130"><template slot-scope="s">{{ actions[s.row.action] || s.row.action }}</template></el-table-column><el-table-column label="问题 / 说明" min-width="330"><template slot-scope="s">{{ eventCategory(s.row) }}<div>{{ s.row.message }}</div><div class="issue-caption">{{ facts(s.row.evidence).join(' · ') }}</div></template></el-table-column></el-table></el-tab-pane>
      </el-tabs>
    </div><span slot="footer"><el-button :loading="loading" :disabled="!!busy" @click="refresh(true)">刷新核对</el-button><el-button :disabled="!!busy" @click="visible=false">关闭</el-button></span>
  </el-dialog>
</template>
<script>
import { orderIssues, recheckOrderIssues, acknowledgeOrderIssue } from '@/api/order'
import { issueCategories, issueScopes, issueStages, issueStates, issueActions, issueTone } from './issueLabels'
export default {
  data() { return { visible: false, loading: false, id: null, orderSn: '', report: {}, error: '', tab: 'active', requestId: 0, busy: null, states: issueStates, actions: issueActions } },
  computed: { active() { return (this.report.issues || []).filter(issue => issue.state !== 'RESOLVED') } },
  watch: { visible(value) { if (!value) this.requestId++ } }, beforeDestroy() { this.requestId++ },
  methods: {
    category(issue) { return issueCategories[issue.category] || issue.category }, scope(issue) { return issueScopes[issue.scope] || issue.scope }, stage(issue) { return issueStages[issue.stage] || issue.stage }, tone: issueTone,
    basis(evidence = {}) { return evidence.basis === 'CURRENT_BALANCE' ? '当前余额与订单来源核对' : evidence.basis === 'ALLOCATION_RESULT' ? '最近分仓结果' : evidence.basis === 'PLATFORM_SHIPPING_TASK' ? '平台回传任务当前结果' : '处理时记录' },
    facts(evidence = {}) { const labels = { required: '需求', reserved: '累计预占', pending: '待预占', locked_reserved: '渠道锁库来源', public_reserved: '公共补占来源', company_available: '当前公司可用', channel_quota: '当前渠道额度', excess_quantity: '超额度预占', shortage_quantity: '实际缺口', pending_allocation: '待分仓' }; return Object.keys(labels).filter(key => evidence[key] !== undefined).map(key => labels[key] + ' ' + evidence[key] + ' 件') },
    eventCategory(event) { const issue = (this.report.issues || []).find(row => row.id === event.issue_id); return issue ? this.category(issue) + ' · ' + (issue.sku_sn || '订单整体') : '问题记录' },
    open(order, tab = 'active') { this.id = order.id; this.orderSn = order.order_sn; this.tab = tab; this.report = {}; this.error = ''; this.visible = true; this.refresh() },
    async refresh(recheck = false) { if (!this.visible) return; const request = ++this.requestId; this.loading = true; this.error = ''; try { const data = (await (recheck ? recheckOrderIssues(this.id) : orderIssues(this.id))).data; if (request !== this.requestId) return; this.report = data; if (recheck) this.$emit('changed') } catch (_) { if (request === this.requestId) this.error = '问题核对未完成，原记录保留，请稍后重试。' } finally { if (request === this.requestId) this.loading = false } },
    async acknowledge(issue) { if (this.busy) return; const order = this.id, request = this.requestId; let note; try { note = (await this.$prompt('记录核对说明；此操作只确认知悉，不解除库存阻断。', '确认已知悉', { inputValidator: value => !!value && value.trim().length > 0 && value.length <= 500, inputErrorMessage: '请填写1至500字说明' })).value } catch (_) { return } if (order !== this.id || request !== this.requestId) return; this.busy = issue.id; try { await acknowledgeOrderIssue(order, issue.id, { note }); if (order !== this.id) return; this.$emit('changed'); await this.refresh() } finally { this.busy = null } }
  }
}
</script>
<style scoped>.issue-dialog-body{max-height:calc(100vh - 240px);overflow:auto;padding-right:4px}.issue-order-number{overflow-wrap:anywhere;font-weight:600;color:#36485f}.issue-caption{font-size:12px;color:#8490a2;line-height:1.7}.issue-card{border:1px solid #e4e9f0;border-radius:8px;padding:14px;margin:12px 0}.issue-card-heading,.issue-evidence{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;font-size:13px;color:#52647c}.issue-card-heading strong{overflow-wrap:anywhere}.issue-message{line-height:1.7;color:#36485f;font-size:13px}.issue-evidence{padding:10px;background:#f7f9fc;border-radius:6px}.blocking{color:#c04b40}.issue-card .el-collapse{border:0;margin-top:8px}.issue-card /deep/ .el-collapse-item__header{font-size:12px;color:#68778d;border:0}.decision-snapshot{font-size:13px;color:#52647c;line-height:1.8}.decision-snapshot span{margin-right:16px}.order-issues-dialog /deep/ .el-dialog{margin-top:5vh!important;margin-bottom:20px}</style>
